import{_ as e,c as i,a as s,b as n,w as d,d as o,r as l,o as h,e as r}from"./app-DTpixBfN.js";import"./vendor-common-BqvKbgTw.js";import"./vendor-katex-DYuN8suk.js";import"./vendor-vuepress-DmiB-O1U.js";const p={};function c(g,t){const a=l("RouteLink");return h(),i("div",null,[t[3]||(t[3]=s("h1",{id:"分析方法与质量标准-过程指标、方法验证与杂质标准-过程指标方法原理与验证",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#分析方法与质量标准-过程指标、方法验证与杂质标准-过程指标方法原理与验证"},[s("span",null,"分析方法与质量标准：过程指标、方法验证与杂质标准：过程指标方法原理与验证")])],-1)),t[4]||(t[4]=s("blockquote",null,[s("p",null,'本页围绕"过程指标、方法验证与杂质标准"中"方法原理与指标认知"核心知识点展开，涵盖关键过程指标（乳酸、氨、糖型）的控制范围、主流分析方法（SEC/CEX/CE-SDS/HPLC-PA）的检测原理、细胞库表征要求、纯度与杂质检定标准，以及生物技术药物检测方法的特殊性与验证框架，共 22 个知识点。')],-1)),t[5]||(t[5]=s("p",null,[s("em",null,"以下内容用于专业学习与团队知识沉淀，具体项目判断请结合产品类型、项目阶段、法规要求和实验数据综合评估。")],-1)),s("ul",null,[s("li",null,[n(a,{to:"/posts/cmc-knowledge/06-analytical-methods-quality-standards-01.html"},{default:d(()=>[...t[0]||(t[0]=[r("返回二级主题总览",-1)])]),_:1})]),s("li",null,[n(a,{to:"/posts/cmc-knowledge/06-analytical-methods-quality-standards.html"},{default:d(()=>[...t[1]||(t[1]=[r("返回一级专题总览",-1)])]),_:1})]),s("li",null,[n(a,{to:"/posts/cmc-knowledge/06-analytical-methods-quality-standards-01-02.html"},{default:d(()=>[...t[2]||(t[2]=[r("下一细分主题",-1)])]),_:1})])]),t[6]||(t[6]=o(`<hr><h2 id="这页先抓重点" tabindex="-1"><a class="header-anchor" href="#这页先抓重点"><span>这页先抓重点</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><ul><li><strong>本页解决的核心问题：</strong> 围绕&quot;方法原理与指标认知&quot;展开，系统覆盖细胞培养关键过程指标的合理控制范围、主流分析方法（SEC-HPLC/CEX-HPLC/CE-SDS/Protein A-HPLC/唾液酸检测）的工作原理与结果解读、GMP 细胞库表征核心检项，以及纯度/残余 DNA/宿主蛋白等杂质指标的法规要求与检定方法。</li><li><strong>最适合在什么时候读：</strong> 已了解分析方法的基本概念，需要深入理解各方法的技术原理、方法选择依据和结果判断逻辑时，从这里入手效率最高。</li><li><strong>建议阅读顺序：</strong> 先读&quot;过程指标控制范围&quot;类问题（建立工艺监控认知基础），再读&quot;分析方法原理&quot;类问题（掌握各方法的技术内核），最后读&quot;杂质标准与验证框架&quot;类问题（理解法规合规要求）。</li><li><strong>使用提醒：</strong> 所有控制范围和方法要求须结合产品类型、开发阶段、数据质量和法规场景综合理解，不得脱离上下文机械套用。</li></ul></div><hr><h2 id="乳酸浓度的合理控制范围与代谢模式判断" tabindex="-1"><a class="header-anchor" href="#乳酸浓度的合理控制范围与代谢模式判断"><span>乳酸浓度的合理控制范围与代谢模式判断</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>乳酸（Lactic Acid）是细胞糖酵解的主要代谢副产物，其在培养液中的积累水平和变化趋势是评估细胞代谢健康状态和工艺稳健性的核心过程指标。</p><h3 id="两种代谢模式与控制标准" tabindex="-1"><a class="header-anchor" href="#两种代谢模式与控制标准"><span>两种代谢模式与控制标准</span></a></h3><p><strong>① 乳酸消耗型（理想模式）</strong></p><table><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td><strong>代谢特征</strong></td><td>培养前期（生长期）产生乳酸，培养中后期（通常第 8～10 天）细胞转换代谢方式，开始消耗乳酸</td></tr><tr><td><strong>收获时乳酸浓度</strong></td><td>通常 <strong>&lt; 1 g/L</strong>，多数情况下接近 0 g/L</td></tr><tr><td><strong>工程优势</strong></td><td>工艺稳健性好，pH 控制容易，易于放大至生产规模，批间一致性高</td></tr><tr><td><strong>代谢切换机制</strong></td><td>细胞在葡萄糖充足时偏向有氧糖酵解产乳酸（Warburg 效应），葡萄糖受限或工艺优化后转向 TCA 循环消耗乳酸</td></tr></tbody></table><p><strong>② 乳酸积累型（需评估管理）</strong></p><table><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td><strong>代谢特征</strong></td><td>培养全程乳酸浓度持续上升，无明显消耗阶段</td></tr><tr><td><strong>可接受控制范围</strong></td><td>培养后期乳酸浓度 <strong>&lt; 2 g/L</strong>，认为风险较低</td></tr><tr><td><strong>超出 2 g/L 的影响</strong></td><td>pH 持续下降 → 须消耗大量碱（NaOH）中和 → 渗透压升高 → 细胞活力下降 → 产量和质量风险升高</td></tr></tbody></table><h3 id="乳酸积累的工艺影响与决策逻辑" tabindex="-1"><a class="header-anchor" href="#乳酸积累的工艺影响与决策逻辑"><span>乳酸积累的工艺影响与决策逻辑</span></a></h3><p>在克隆筛选阶段，不应仅因乳酸积累问题排除高产量/优质量的克隆，<strong>应综合评估</strong>：</p><table><thead><tr><th>评估因素</th><th>权重建议</th></tr></thead><tbody><tr><td>产物表达量（滴度）</td><td>高权重（商业可行性决定因素）</td></tr><tr><td>产品质量属性（CQA）</td><td>高权重（安全性/有效性核心）</td></tr><tr><td>乳酸积累水平</td><td>中权重（可通过培养基和工艺优化改善）</td></tr></tbody></table><p><strong>改善乳酸积累的上游调控手段：</strong></p><ul><li><strong>葡萄糖控制策略：</strong> 降低培养基中葡萄糖浓度或采用反馈控制补料，维持低葡萄糖浓度（&lt; 5 mM）迫使细胞更多地利用氧化磷酸化</li><li><strong>培养基优化：</strong> 添加半乳糖替代葡萄糖（半乳糖代谢速率慢，产乳酸少）；补充谷氨酰胺类似物（如谷氨酰胺二肽）减少氨和乳酸的协同积累</li><li><strong>温度偏移：</strong> 培养后期降温（如 37°C → 33°C）可减缓糖酵解速率，促进线粒体代谢</li><li><strong>CO₂ 控制：</strong> 高 pCO₂ 会抑制乳酸消耗，须通过通气策略及时吹扫 CO₂</li></ul><h3 id="乳酸检测方法" tabindex="-1"><a class="header-anchor" href="#乳酸检测方法"><span>乳酸检测方法</span></a></h3><p>生产过程中通常采用在线或离线生化分析仪（如 Bioprofile FLEX、Nova BioProfile）实时监测乳酸浓度，检测频率通常为每 12～24 小时一次，作为标准中间体过程控制（IPC）指标。</p></div><hr><h2 id="氨浓度的合理控制范围与对细胞培养的多维影响" tabindex="-1"><a class="header-anchor" href="#氨浓度的合理控制范围与对细胞培养的多维影响"><span>氨浓度的合理控制范围与对细胞培养的多维影响</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>氨（NH₃/NH₄⁺）是细胞培养中谷氨酰胺代谢和氨基酸分解代谢的主要副产物，在培养液中随时间积累，是仅次于乳酸的第二大代谢毒性物质。</p><h3 id="控制范围" tabindex="-1"><a class="header-anchor" href="#控制范围"><span>控制范围</span></a></h3><p><strong>推荐控制上限：通常 ≤ 10 mM（Case by Case，须结合具体细胞系和工艺数据确定）</strong></p><h3 id="文献报道的关键毒性阈值" tabindex="-1"><a class="header-anchor" href="#文献报道的关键毒性阈值"><span>文献报道的关键毒性阈值</span></a></h3><table><thead><tr><th>研究来源</th><th>氨浓度</th><th>观察到的效应</th></tr></thead><tbody><tr><td>Kurano 等</td><td>8 mM</td><td>CHO 细胞<strong>比生长速率下降 80%</strong>（严重抑制增殖）</td></tr><tr><td>Hansen 等</td><td>8 mM</td><td>目标产物（tPA）<strong>比生产速率（qP）下降</strong></td></tr><tr><td>Borys 等</td><td>—</td><td>CHO 细胞表达的抗体<strong>糖基化受氨浓度影响</strong>（糖型谱改变）</td></tr></tbody></table><h3 id="氨对细胞培养的三重负面影响" tabindex="-1"><a class="header-anchor" href="#氨对细胞培养的三重负面影响"><span>氨对细胞培养的三重负面影响</span></a></h3><p><strong>① 抑制细胞生长</strong></p><ul><li>氨通过干扰 TCA 循环（抑制 α-酮戊二酸脱氢酶）和影响氨基酸代谢，导致细胞能量代谢障碍</li><li>高浓度氨（&gt; 10 mM）诱导细胞周期停滞（G₁期阻滞）和细胞凋亡</li></ul><p><strong>② 降低产品产量</strong></p><ul><li>细胞生长受抑 → 有效生产细胞数量减少 → 单位体积产量（g/L）下降</li><li>高氨环境下细胞的比生产速率（qP）也可能降低</li></ul><p><strong>③ 影响产品糖基化质量</strong></p><ul><li>氨浓度升高影响高尔基体腔内 pH（氨为弱碱，穿透细胞膜进入细胞器），干扰 pH 依赖性糖基化酶的活性</li><li>可观察到的糖型变化：半乳糖化程度降低、唾液酸化程度改变、高甘露糖型比例波动</li></ul><h3 id="氨积累的控制策略" tabindex="-1"><a class="header-anchor" href="#氨积累的控制策略"><span>氨积累的控制策略</span></a></h3><table><thead><tr><th>策略</th><th>原理</th></tr></thead><tbody><tr><td><strong>降低谷氨酰胺浓度</strong></td><td>谷氨酰胺是氨的最大产生来源，降低初始浓度或采用分次补料可减少氨积累</td></tr><tr><td><strong>使用谷氨酰胺二肽（Ala-Gln）</strong></td><td>二肽形式在细胞外稳定，进入细胞后缓慢释放谷氨酰胺，减少胞外氨积累</td></tr><tr><td><strong>优化补料策略</strong></td><td>减少过量氨基酸的补加，避免氨基酸过剩引发分解代谢产氨</td></tr><tr><td><strong>pH 控制精细化</strong></td><td>维持培养液 pH 在设定范围内，避免碱性偏移促进氨的非离子化（NH₄⁺ ⇌ NH₃），NH₃ 渗透性更强，毒性更大</td></tr></tbody></table></div><hr><h2 id="常见-n-糖糖型的种类、控制范围与检测要求" tabindex="-1"><a class="header-anchor" href="#常见-n-糖糖型的种类、控制范围与检测要求"><span>常见 N 糖糖型的种类、控制范围与检测要求</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>单克隆抗体 N 糖基化谱（Glycan Profile）是重要的 CQA，须在整个产品生命周期中系统监控。四种核心糖型修饰的控制范围基于 A-Mab 案例研究（行业参考值），具体产品须结合临床和工艺数据确定。</p><h3 id="四种核心糖型控制范围汇总" tabindex="-1"><a class="header-anchor" href="#四种核心糖型控制范围汇总"><span>四种核心糖型控制范围汇总</span></a></h3><table><thead><tr><th>糖型</th><th>控制范围参考值</th><th>对活性的主要影响</th><th>主要调控手段</th></tr></thead><tbody><tr><td><strong>岩藻糖化（Fucosylation）</strong></td><td>2%～13%（去岩藻糖化比例）</td><td>核心岩藻糖是 ADCC 活性的决定因素（去岩藻糖化 → ADCC ↑↑）</td><td>渗透压、Mn²⁺；FUT8 细胞株工程</td></tr><tr><td><strong>半乳糖化（Galactosylation）</strong></td><td>10%～40%</td><td>半乳糖化增加 → CDC ↑；与 ADCC 协同</td><td>添加微量 Mn²⁺（1～10 μM）；低温培养；延长培养时间</td></tr><tr><td><strong>唾液酸化（Sialylation）</strong></td><td>0%～2%</td><td>ADCC ↓；抗炎活性 ↑；增加负电荷（pI 降低）</td><td>CHO 细胞天然唾液酸化水平低，通常不需主动抑制</td></tr><tr><td><strong>高甘露糖（High Mannose，Man5+）</strong></td><td>0%～10%（通常 3%～10%）</td><td>甘露糖受体介导加速清除（PK 影响）；ADCC 活性降低</td><td>保持充足 DO；优化温度和培养周期</td></tr></tbody></table><h3 id="糖型检测的主流方法" tabindex="-1"><a class="header-anchor" href="#糖型检测的主流方法"><span>糖型检测的主流方法</span></a></h3><table><thead><tr><th>检测方法</th><th>原理</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>荧光标记 N 糖谱分析（HILIC-FLD）</strong></td><td>用 2-AB（2-氨基苯甲酰胺）或 InstantAB 荧光标记释放的 N 糖，经亲水作用色谱（HILIC）分离后荧光检测</td><td>批放行糖型定量；稳定性研究</td></tr><tr><td><strong>质谱（LC-MS/MS）</strong></td><td>直接检测糖肽或完整 N 糖的分子量，精确鉴定糖型结构</td><td>糖型鉴定；异常糖型结构解析</td></tr><tr><td><strong>毛细管电泳（CE-LIF）</strong></td><td>荧光标记 N 糖后经毛细管电泳分离，激光诱导荧光检测</td><td>高通量筛选；部分批放行应用</td></tr></tbody></table><h3 id="批间糖型一致性的管理要求" tabindex="-1"><a class="header-anchor" href="#批间糖型一致性的管理要求"><span>批间糖型一致性的管理要求</span></a></h3><ul><li>须在稳定性研究中监测糖型随时间的变化趋势</li><li>工艺变更（如培养基批次变更、温度偏移策略调整）须评估对糖型谱的影响</li><li>商业化生产阶段须通过持续工艺验证（CPV）建立糖型批间变异的历史统计基准</li></ul></div><hr><h2 id="基因拷贝数的定义、检测方法与稳定性风险" tabindex="-1"><a class="header-anchor" href="#基因拷贝数的定义、检测方法与稳定性风险"><span>基因拷贝数的定义、检测方法与稳定性风险</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>基因拷贝数（Gene Copy Number，GCN）是衡量外源目的基因在宿主细胞基因组中整合数量的关键参数，是细胞株遗传稳定性研究和细胞库表征的重要内容。</p><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>基因拷贝数指某一特定基因或 DNA 序列在<strong>单倍体基因组</strong>中出现的数目。对于 CHO 细胞（二倍体），测定值通常以每个细胞的拷贝数表示。</p><h3 id="检测方法" tabindex="-1"><a class="header-anchor" href="#检测方法"><span>检测方法</span></a></h3><table><thead><tr><th>方法</th><th>原理</th><th>优势</th><th>局限性</th></tr></thead><tbody><tr><td><strong>Southern Blot</strong></td><td>限制性内切酶消化基因组 DNA，电泳分离后转膜，与标记探针杂交</td><td>金标准方法，可同时分析整合位点模式</td><td>操作复杂；周期长；半定量</td></tr><tr><td><strong>荧光定量 PCR（qPCR）</strong></td><td>实时 PCR 扩增目的基因片段，以内参基因（单拷贝基因）为参照计算相对拷贝数</td><td>灵敏、快速、高通量；适合常规检测</td><td>须设计高特异性引物/探针；须有可靠内参</td></tr><tr><td><strong>数字 PCR（ddPCR）</strong></td><td>将样品分割为数万个微液滴，每液滴中进行单分子 PCR，直接计数阳性液滴数</td><td><strong>绝对定量</strong>，无需标准曲线；准确度最高</td><td>设备成本高；通量相对较低</td></tr></tbody></table><h3 id="拷贝数丢失-gene-copy-loss-的原因与风险" tabindex="-1"><a class="header-anchor" href="#拷贝数丢失-gene-copy-loss-的原因与风险"><span>拷贝数丢失（Gene Copy Loss）的原因与风险</span></a></h3><p>基因拷贝数丢失是细胞株遗传不稳定性的重要体现，主要原因包括：</p><table><thead><tr><th>原因</th><th>机制</th></tr></thead><tbody><tr><td><strong>整合位点不稳定性</strong></td><td>外源基因整合在基因组异染色质区或不稳定区域，易发生重排或缺失</td></tr><tr><td><strong>选择压力撤除</strong></td><td>使用药物筛选（MTX/MSX）建库后，一旦撤除选择压力，部分高拷贝细胞因维持额外拷贝的代谢负担而被低拷贝细胞超越</td></tr><tr><td><strong>外源基因重组</strong></td><td>多拷贝整合中，同源序列之间发生同源重组，导致拷贝数减少</td></tr><tr><td><strong>传代过程中的随机丢失</strong></td><td>长期传代过程中，自发的染色体重排可能影响整合位点完整性</td></tr></tbody></table><p><strong>实践含义：</strong> 细胞株稳定性研究须在最高限定代次（EOPC）时检测拷贝数，与 MCB 建库时的拷贝数进行比较，确认传代过程中拷贝数无显著变化（通常要求变化 &lt; 30%）。</p></div><hr><h2 id="gmp-细胞库表征的检定项目体系" tabindex="-1"><a class="header-anchor" href="#gmp-细胞库表征的检定项目体系"><span>GMP 细胞库表征的检定项目体系</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>GMP 细胞库（MCB 和 WCB）的检定是保证生物制品安全性的基础，须按照各国药典和指导原则的规定系统开展，不同监管市场的具体要求存在差异。</p><h3 id="各国法规适用性" tabindex="-1"><a class="header-anchor" href="#各国法规适用性"><span>各国法规适用性</span></a></h3><table><thead><tr><th>申报市场</th><th>适用法规依据</th></tr></thead><tbody><tr><td><strong>中国（NMPA）</strong></td><td>《中国药典》三部&quot;生物制品生产检定用动物细胞基质制备和检定规程&quot;</td></tr><tr><td><strong>美国（FDA）</strong></td><td>USP ⟨1050⟩（病毒安全性）、ICH Q5A/Q5D、21 CFR 相关要求</td></tr><tr><td><strong>欧盟（EMA）</strong></td><td>EudraLex Volume 4 Annex 2、ICH Q5A/Q5D</td></tr></tbody></table><h3 id="gmp-细胞库表征核心检定项目" tabindex="-1"><a class="header-anchor" href="#gmp-细胞库表征核心检定项目"><span>GMP 细胞库表征核心检定项目</span></a></h3><p><strong>① 细胞鉴别试验（Identity Testing）</strong></p><table><thead><tr><th>方法</th><th>检定内容</th></tr></thead><tbody><tr><td>STR（短串联重复序列）基因型分析</td><td>确认细胞系身份，排除细胞交叉污染</td></tr><tr><td>同工酶分析（Isoenzyme Analysis）</td><td>确认物种来源（CHO 细胞的特征酶谱）</td></tr><tr><td>核型分析（Karyotyping）</td><td>评估染色体数目和结构的稳定性</td></tr><tr><td>目的基因测序</td><td>确认表达构建体的序列完整性（与 ICH Q5B 要求一致）</td></tr></tbody></table><p><strong>② 无菌检查（微生物安全性）</strong></p><ul><li>细菌检查（需氧和厌氧条件）</li><li>真菌检查</li><li>分枝杆菌（Mycobacteria）检测</li></ul><p><strong>③ 支原体检查</strong></p><ul><li>培养法（周期约 28 天）+ 荧光染色法并行（药典双法要求）</li><li>可辅以 PCR 法（须经方法验证，作为补充）</li></ul><p><strong>④ 内源性病毒因子检查</strong></p><ul><li>逆转录病毒检测（透射电镜、逆转录酶活性检测、感染性测定）</li><li>特别针对 CHO 细胞：检测鼠白血病病毒相关序列（MLVS）</li></ul><p><strong>⑤ 外源性病毒因子检查</strong></p><ul><li>体内法：多种动物模型（乳鼠、豚鼠、兔子等）接种</li><li>体外法：多种指示细胞系（Vero、MRC-5 等）培养观察</li><li>特定病毒 PCR（针对猪源病毒 PPV、PCV；牛源病毒 BVDV 等）</li></ul><p><strong>⑥ 成瘤性和致瘤性检查</strong></p><ul><li>成瘤性（Tumorigenicity）：裸鼠皮下注射试验，观察肿瘤形成</li><li>致瘤性（Oncogenicity）：细胞 DNA 的转化能力检测</li></ul><h3 id="不同细胞库类型的检定要求差异" tabindex="-1"><a class="header-anchor" href="#不同细胞库类型的检定要求差异"><span>不同细胞库类型的检定要求差异</span></a></h3><table><thead><tr><th>细胞库类型</th><th>检定深度</th><th>法规要求</th></tr></thead><tbody><tr><td>RCB / PCB</td><td>有限检定（支原体 + 无菌）</td><td>非 GMP 阶段，最低要求</td></tr><tr><td><strong>MCB</strong></td><td><strong>全面检定（一次性）</strong></td><td>GMP 建库后须完成</td></tr><tr><td><strong>WCB</strong></td><td><strong>按规定项目检定（每次新建）</strong></td><td>每次从 MCB 建立新 WCB 均须检定</td></tr><tr><td><strong>EOPC</strong></td><td><strong>全面检定（至少一次）</strong></td><td>工艺变更后须重新检定</td></tr></tbody></table></div><hr><h2 id="片段与聚体的检测方法-ce-sds-与-sec-的选择原则" tabindex="-1"><a class="header-anchor" href="#片段与聚体的检测方法-ce-sds-与-sec-的选择原则"><span>片段与聚体的检测方法：CE-SDS 与 SEC 的选择原则</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>片段（Fragments）和聚体（Aggregates）是单抗制品中最重要的产品相关杂质，须采用互补的分析方法进行定量检测。</p><h3 id="检测方法矩阵" tabindex="-1"><a class="header-anchor" href="#检测方法矩阵"><span>检测方法矩阵</span></a></h3><table><thead><tr><th>杂质类型</th><th>推荐方法</th><th>备用方法</th><th>检测原理</th></tr></thead><tbody><tr><td><strong>片段（Fragments）</strong></td><td><strong>CE-SDS（NR 模式）</strong></td><td>SDS-PAGE（非还原）</td><td>基于分子量大小的电泳分离；片段分子量小于完整抗体</td></tr><tr><td><strong>聚体（Aggregates）</strong></td><td><strong>SEC-HPLC</strong></td><td>SDS-PAGE（非还原）</td><td>基于分子大小的色谱分离；聚体分子量大于单体</td></tr></tbody></table><h3 id="两种方法的互补性" tabindex="-1"><a class="header-anchor" href="#两种方法的互补性"><span>两种方法的互补性</span></a></h3><p><strong>CE-SDS 的优势：</strong></p><ul><li>检测灵敏度高，可检出 &lt; 1% 的低分子量变体（LMW）</li><li>可区分轻链（LC）、重链（HC）、半抗体（HL）等具体片段种类（还原模式）</li><li>自动化程度高，批间重现性好</li></ul><p><strong>SEC-HPLC 的优势：</strong></p><ul><li>在天然非变性条件下检测，反映蛋白质的真实聚合状态</li><li>可区分单体、二聚体和高聚体（基于保留时间）</li><li>定量准确，与光散射（MALS）联用可获得分子量信息</li></ul><p><strong>SDS-PAGE 的局限性（作为参考）：</strong></p><ul><li>半定量方法，检测灵敏度低于 CE-SDS 和 SEC-HPLC</li><li>消耗样品量大；银染法需 ≥ 5 μg，考马斯蓝法需 ≥ 10 μg</li><li>操作复杂，批间重现性相对较低</li><li>通常作为 CE-SDS 和 SEC-HPLC 的补充验证，不单独用于批放行</li></ul><h3 id="检测结果解读要点" tabindex="-1"><a class="header-anchor" href="#检测结果解读要点"><span>检测结果解读要点</span></a></h3><ul><li><strong>SEC-HPLC 结果：</strong> 主峰（单体）出峰时间晚，聚体先出峰（大分子被排阻，在多孔凝胶中停留时间短）；面积归一化后报告各峰百分比</li><li><strong>CE-SDS（NR 模式）结果：</strong> 轻链（LC）分子量最小，最先迁移；完整抗体（主峰）最后迁移；结果以主峰面积百分比报告产品纯度</li></ul></div><hr><h2 id="电荷异质性的表征方法-ief-与-iex-的原理与应用" tabindex="-1"><a class="header-anchor" href="#电荷异质性的表征方法-ief-与-iex-的原理与应用"><span>电荷异质性的表征方法：IEF 与 IEX 的原理与应用</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>单克隆抗体的电荷异质性（Charge Heterogeneity）表征是产品质量属性分析的核心内容，须通过至少一种主要分析方法进行系统表征，并在批放行中纳入监控。</p><h3 id="两大主流表征方法" tabindex="-1"><a class="header-anchor" href="#两大主流表征方法"><span>两大主流表征方法</span></a></h3><p><strong>① 等电聚焦电泳（Isoelectric Focusing，IEF）及其衍生技术</strong></p><table><thead><tr><th>技术形式</th><th>检测原理</th><th>特点</th></tr></thead><tbody><tr><td>凝胶 IEF</td><td>蛋白质在 pH 梯度凝胶中迁移，至净电荷为零（等电点）时停止</td><td>半定量；可目测 pI 值；分辨率中等</td></tr><tr><td><strong>cIEF（毛细管等电聚焦）</strong></td><td>毛细管中建立 pH 梯度，蛋白质聚焦后整体推动至检测窗口，UV 280 nm 检测</td><td>高分辨率；定量；给出 pI 分布</td></tr><tr><td><strong>icIEF（成像 cIEF）</strong></td><td>cIEF 的升级版，全程 CCD 成像记录聚焦过程</td><td>最高通量；无需推动步骤；自动化程度最高</td></tr></tbody></table><p><strong>② 离子交换层析（Ion Exchange Chromatography，IEX）</strong></p><table><thead><tr><th>技术形式</th><th>适用条件</th><th>峰出现顺序</th></tr></thead><tbody><tr><td><strong>CEX-HPLC（阳离子交换，最常用）</strong></td><td>单抗 pI 通常 &gt; 7，在中性 pH 下带正电，与 CEX 填料结合；适合大多数 IgG</td><td>酸性峰（pI 低，保留时间短）→ 主峰 → 碱性峰（pI 高，保留时间长）</td></tr><tr><td><strong>AEX-HPLC（阴离子交换）</strong></td><td>与 CEX 互补；pI 偏低的蛋白质（如某些抗体片段）适用</td><td>碱性峰先洗脱 → 主峰 → 酸性峰</td></tr></tbody></table><h3 id="酸性-碱性变体在不同方法中的行为汇总" tabindex="-1"><a class="header-anchor" href="#酸性-碱性变体在不同方法中的行为汇总"><span>酸性/碱性变体在不同方法中的行为汇总</span></a></h3><table><thead><tr><th>变体类型</th><th>IEF 位置</th><th>CEX-HPLC 位置</th><th>AEX-HPLC 位置</th></tr></thead><tbody><tr><td>酸性变体</td><td>pI 低于主峰，位于低 pH 侧</td><td>早于主峰出峰（保留弱）</td><td>晚于主峰出峰（保留强）</td></tr><tr><td>主峰</td><td>中间位置</td><td>中间位置</td><td>中间位置</td></tr><tr><td>碱性变体</td><td>pI 高于主峰，位于高 pH 侧</td><td>晚于主峰出峰（保留强）</td><td>早于主峰出峰（保留弱）</td></tr></tbody></table><h3 id="进阶分析-电荷变体结构鉴定" tabindex="-1"><a class="header-anchor" href="#进阶分析-电荷变体结构鉴定"><span>进阶分析：电荷变体结构鉴定</span></a></h3><p>当批次间或批次内的电荷异质性谱发生变化时，须进行结构根因分析：</p><ul><li><strong>肽图（Peptide Mapping）+ LC-MS/MS：</strong> 精确定位化学修饰（去酰胺化、氧化、糖化等）在序列中的位置</li><li><strong>酶处理 + 色谱分析：</strong> PNGase F 去除 N 糖后分析，区分糖基化引起的电荷变化与其他修饰</li></ul></div><hr><h2 id="protein-a-hplc-pa-hplc-测定上清液滴度的原理与流程" tabindex="-1"><a class="header-anchor" href="#protein-a-hplc-pa-hplc-测定上清液滴度的原理与流程"><span>Protein A-HPLC（PA-HPLC）测定上清液滴度的原理与流程</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>基于 Protein A 亲和色谱的 HPLC 方法（PA-HPLC）是细胞培养上清液中抗体浓度（Titer）测定的行业标准方法，兼具高特异性、高灵敏度和快速定量的优点。</p><h3 id="检测原理" tabindex="-1"><a class="header-anchor" href="#检测原理"><span>检测原理</span></a></h3><p><strong>核心利用金黄色葡萄球菌 Protein A 与 IgG Fc 区的高度特异性结合：</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>上清液加载至 Protein A 色谱柱</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>IgG 与 Protein A 特异性结合 → 吸附在柱上</span></span>
<span class="line"><span>杂质（HCP、培养基成分等）→ 流穿或被洗涤去除</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>强酸性缓冲液洗脱（pH 3.0～3.4）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>紫外吸光度检测（280 nm）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>以已知浓度标准品建立标准曲线</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>根据消光系数（Extinction Coefficient）换算 Titer 值</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="关键参数与注意事项" tabindex="-1"><a class="header-anchor" href="#关键参数与注意事项"><span>关键参数与注意事项</span></a></h3><table><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><strong>消光系数（ε₂₈₀）</strong></td><td>不同抗体的 ε₂₈₀ 不同（通常 1.3～1.7 AU·mL/mg·cm），须根据氨基酸序列计算或实验测定</td></tr><tr><td><strong>标准品选择</strong></td><td>通常使用与待测样品同类型的参比抗体（Reference Standard），或使用氨基酸分析法校正的浓度标准品</td></tr><tr><td><strong>线性范围</strong></td><td>须在方法验证中确定，避免在线性范围外检测导致系统误差</td></tr><tr><td><strong>洗脱液中性化</strong></td><td>洗脱液 pH 约 3.0，须立即中和，避免蛋白在低 pH 下长时间暴露导致检测误差</td></tr></tbody></table><h3 id="pa-hplc-与其他-titer-检测方法的比较" tabindex="-1"><a class="header-anchor" href="#pa-hplc-与其他-titer-检测方法的比较"><span>PA-HPLC 与其他 Titer 检测方法的比较</span></a></h3><table><thead><tr><th>方法</th><th>原理</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>PA-HPLC</strong></td><td>Protein A 亲和色谱 + UV 检测</td><td>高特异性；定量准确；可批量检测</td><td>批放行；工艺监控</td></tr><tr><td><strong>BCA/Bradford 法</strong></td><td>总蛋白定量</td><td>非特异性（检测所有蛋白）；操作简便</td><td>样品预筛；非 GMP 环境</td></tr><tr><td><strong>ELISA（抗体特异性）</strong></td><td>免疫亲和检测</td><td>高灵敏度；可检测极低浓度</td><td>极低 Titer 样品；特异性要求高场景</td></tr><tr><td><strong>BLI/SPR（生物层干涉/表面等离子体共振）</strong></td><td>实时分子相互作用检测</td><td>快速；无需标记；可同时测定亲和力</td><td>高通量筛选；QC 过程监控</td></tr></tbody></table></div><hr><h2 id="sec-hplc-的检测原理、方法要点与结果解读" tabindex="-1"><a class="header-anchor" href="#sec-hplc-的检测原理、方法要点与结果解读"><span>SEC-HPLC 的检测原理、方法要点与结果解读</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>尺寸排阻色谱（Size Exclusion Chromatography，SEC）/ 分子排阻液相色谱法（SE-HPLC）是单抗制品聚体含量检测和单体纯度评估的最重要分析方法，也是批放行的必检项目。</p><h3 id="检测原理-1" tabindex="-1"><a class="header-anchor" href="#检测原理-1"><span>检测原理</span></a></h3><p><strong>以多孔性凝胶为固定相，依据分子流体力学体积（Hydrodynamic Volume）进行分离：</strong></p><table><thead><tr><th>分子类型</th><th>行为</th><th>洗脱顺序</th></tr></thead><tbody><tr><td><strong>聚体（大分子，HMW）</strong></td><td>分子尺寸超过凝胶孔径，被排阻，沿凝胶粒子外部空隙（死体积）快速通过</td><td><strong>先洗脱</strong></td></tr><tr><td><strong>单体（目标产品，~150 kDa）</strong></td><td>部分进入凝胶孔洞，停留时间中等</td><td><strong>中间洗脱</strong></td></tr><tr><td><strong>片段（低分子量，LMW）</strong></td><td>充分渗透入凝胶孔洞，保留时间最长</td><td><strong>最后洗脱</strong></td></tr></tbody></table><h3 id="方法开发关键要点" tabindex="-1"><a class="header-anchor" href="#方法开发关键要点"><span>方法开发关键要点</span></a></h3><table><thead><tr><th>参数</th><th>优化原则</th></tr></thead><tbody><tr><td><strong>色谱柱选择</strong></td><td>须选择合适的分子量分离范围（通常 10 kDa～1,000 kDa 覆盖范围）；常用柱型：TSKgel G3000SWXL、Tosoh G3000SW、Superdex 200</td></tr><tr><td><strong>流动相</strong></td><td>高盐磷酸盐缓冲液（通常 100～200 mM 磷酸钠 + 100 mM 硫酸钠，pH 6.8～7.0），高离子强度可抑制蛋白与填料的非特异性相互作用</td></tr><tr><td><strong>流速</strong></td><td>通常 0.5～1.0 mL/min（须在分辨率和运行时间之间平衡）</td></tr><tr><td><strong>检测波长</strong></td><td>280 nm（蛋白质主要吸收波长）</td></tr><tr><td><strong>上样量</strong></td><td>通常 50～200 μg（须在线性范围内）</td></tr><tr><td><strong>系统适用性</strong></td><td>每次运行须通过系统适用性测试（SST）：分辨率、理论塔板数、拖尾因子须符合规定</td></tr></tbody></table><h3 id="结果解读与报告方式" tabindex="-1"><a class="header-anchor" href="#结果解读与报告方式"><span>结果解读与报告方式</span></a></h3><ul><li><strong>面积归一化法：</strong> 各峰面积 / 总峰面积 × 100% = 各组分百分比</li><li><strong>典型报告指标：</strong> 单体（Monomer）%、聚体（HMW）%、片段（LMW）%</li><li><strong>放行标准示例：</strong> 单体纯度 ≥ 95%，聚体 ≤ 5%（具体须基于产品 CQA 评估确定）</li></ul></div><hr><h2 id="cex-hplc-的检测原理、洗脱模式与结果解读" tabindex="-1"><a class="header-anchor" href="#cex-hplc-的检测原理、洗脱模式与结果解读"><span>CEX-HPLC 的检测原理、洗脱模式与结果解读</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>阳离子交换色谱（CEX-HPLC）是单克隆抗体电荷异质性检测的核心分析方法，通过高分辨率分离酸性变体、主峰和碱性变体，反映产品电荷分布的均一性。</p><h3 id="检测原理-2" tabindex="-1"><a class="header-anchor" href="#检测原理-2"><span>检测原理</span></a></h3><p><strong>基于蛋白质表面净电荷差异进行分离：</strong></p><ul><li>在特定 pH 条件下（低于抗体 pI，通常 pH 4.5～6.5），单克隆抗体（pI 通常 &gt; 8）带正电荷，与阳离子交换填料的负电荷配基（磺酸基 −SO₃⁻）发生静电结合</li><li>带电量不同的蛋白质（电荷变体）与填料的亲和力不同，通过改变离子强度（盐梯度）或 pH，按亲和力从小到大依次洗脱</li></ul><h3 id="两种洗脱方式的选择" tabindex="-1"><a class="header-anchor" href="#两种洗脱方式的选择"><span>两种洗脱方式的选择</span></a></h3><table><thead><tr><th>洗脱方式</th><th>适用场景</th><th>缓冲液体系</th><th>优缺点</th></tr></thead><tbody><tr><td><strong>盐梯度洗脱（NaCl 梯度）</strong></td><td>项目前期（未知目标 pI）；方法开发初期</td><td>常用 pH 6.5 的 MES 缓冲液 + NaCl 梯度</td><td>操作简单；对不同 pI 的蛋白质通用性好；但分辨率通常低于 pH 梯度</td></tr><tr><td><strong>pH 梯度洗脱（最常用）</strong></td><td>项目中后期；批放行方法</td><td>多种 pH 缓冲液组合形成 pH 梯度（通常从 pH 5.5 至 pH 9.0）</td><td><strong>分辨率更高</strong>；峰形更好；对电荷变体区分能力强；须精确配制和质控缓冲液</td></tr></tbody></table><h3 id="典型-cex-色谱图解读" tabindex="-1"><a class="header-anchor" href="#典型-cex-色谱图解读"><span>典型 CEX 色谱图解读</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>↑ UV 280 nm 信号</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>|        酸性峰群          主峰           碱性峰群</span></span>
<span class="line"><span>|      (Acidic Peaks)   (Main Peak)    (Basic Peaks)</span></span>
<span class="line"><span>|    ___/\\___           ___/\\___         __/\\__</span></span>
<span class="line"><span>|___/        \\___________/       \\_______/      \\___</span></span>
<span class="line"><span>                                                   → 时间（分钟）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>酸性变体</strong>（先洗脱）：包含去酰胺化产物（Asn→Asp）、唾液酸化变体、糖化产物等</li><li><strong>主峰</strong>（中间洗脱）：产品主要组分，代表目标抗体</li><li><strong>碱性变体</strong>（后洗脱）：包含 C 末端 Lys 保留、N 末端 pyrGlu 未形成等变体</li></ul><h3 id="cex-方法在工艺开发中的应用" tabindex="-1"><a class="header-anchor" href="#cex-方法在工艺开发中的应用"><span>CEX 方法在工艺开发中的应用</span></a></h3><ul><li><strong>克隆筛选：</strong> 比较不同克隆的电荷变体分布，选择电荷均一性好的克隆</li><li><strong>工艺优化：</strong> 评估 pH、温度、培养时间等工艺参数对电荷变体比例的影响</li><li><strong>稳定性研究：</strong> 监测电荷变体随储存时间的变化趋势（特别是酸性峰的增长）</li><li><strong>可比性研究：</strong> 工艺变更前后的电荷谱比较，判断变更对产品质量的影响</li></ul></div><hr><h2 id="ce-sds-nr-与-r-模式-的检测原理与结果解读" tabindex="-1"><a class="header-anchor" href="#ce-sds-nr-与-r-模式-的检测原理与结果解读"><span>CE-SDS（NR 与 R 模式）的检测原理与结果解读</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>毛细管凝胶电泳（Capillary Electrophoresis-Sodium Dodecyl Sulfate，CE-SDS）是替代传统 SDS-PAGE 进行蛋白质纯度和片段分析的自动化高精度方法，分为非还原（NR）和还原（R）两种模式，提供互补信息。</p><h3 id="检测原理-3" tabindex="-1"><a class="header-anchor" href="#检测原理-3"><span>检测原理</span></a></h3><p><strong>CE-SDS 的核心分离机制：</strong></p><ul><li>SDS（十二烷基硫酸钠）与蛋白质结合，使蛋白质变性并赋予均一的负电荷（按质量计），消除蛋白质自身电荷差异</li><li>在高压直流电场（通常 15～30 kV）驱动下，蛋白质在毛细管中的填充凝胶（分子筛）中按<strong>分子量大小</strong>迁移分离</li><li>分子量小的片段迁移速度快（先检测到），分子量大的聚体迁移速度慢（后检测到）</li></ul><h3 id="nr-模式-非还原-non-reducing-nr-ce-sds" tabindex="-1"><a class="header-anchor" href="#nr-模式-非还原-non-reducing-nr-ce-sds"><span>NR 模式（非还原，Non-Reducing，NR-CE-SDS）</span></a></h3><p><strong>样品处理：</strong> 不添加还原剂，保留分子内二硫键，检测抗体的天然组装形式。</p><p><strong>典型峰型与成分（按迁移顺序，从快到慢）：</strong></p><table><thead><tr><th>峰名称</th><th>对应成分</th><th>说明</th></tr></thead><tbody><tr><td>LMW 峰群</td><td>低分子量片段（如 LC 游离、Fab 片段等）</td><td>聚合物的降解产物</td></tr><tr><td>HC 峰</td><td>游离重链</td><td>通常极少量</td></tr><tr><td>HL 峰</td><td>半抗体（一条重链 + 一条轻链）</td><td>分子量约 75 kDa</td></tr><tr><td>HHL 峰</td><td>2/3 抗体（两条重链 + 一条轻链）</td><td>分子量约 125 kDa</td></tr><tr><td><strong>主峰（mAb 峰）</strong></td><td><strong>完整抗体（主要成分）</strong></td><td>分子量约 150 kDa，即产品纯度</td></tr><tr><td>HMW 峰</td><td>聚体</td><td>分子量 &gt; 150 kDa</td></tr></tbody></table><p><strong>结果报告：</strong> 采用面积归一法，主峰面积 / 总峰面积 × 100% = 产品纯度；HHL 和其余片段归入 LMW 计算。</p><h3 id="r-模式-还原-reducing-r-ce-sds" tabindex="-1"><a class="header-anchor" href="#r-模式-还原-reducing-r-ce-sds"><span>R 模式（还原，Reducing，R-CE-SDS）</span></a></h3><p><strong>样品处理：</strong> 添加二硫苏糖醇（DTT）或 β-巯基乙醇，打断所有二硫键，将抗体拆解为独立的轻链（LC）和重链（HC）。</p><p><strong>典型峰型（按迁移顺序）：</strong></p><table><thead><tr><th>峰名称</th><th>对应成分</th><th>分子量（约）</th></tr></thead><tbody><tr><td>LC 峰</td><td>轻链（Light Chain）</td><td>~25 kDa</td></tr><tr><td>NGHC 峰</td><td>去糖基化重链（Non-glycosylated HC）</td><td>~50 kDa</td></tr><tr><td>HC 峰</td><td>糖基化重链（Heavy Chain，含 N 糖）</td><td>~55 kDa</td></tr></tbody></table><p><strong>结果报告：</strong> 轻链（LC%）、NGHC%（去糖基化重链）、HC%（糖基化重链），三者比例反映产品链组成的均一性；LC：HC 的理想比例约为 1:1（IgG 型抗体）。</p><h3 id="nr-与-r-模式的互补应用" tabindex="-1"><a class="header-anchor" href="#nr-与-r-模式的互补应用"><span>NR 与 R 模式的互补应用</span></a></h3><table><thead><tr><th>信息类型</th><th>NR 模式</th><th>R 模式</th></tr></thead><tbody><tr><td>产品纯度（完整抗体）</td><td>✅ 直接检测</td><td>—</td></tr><tr><td>片段和聚体检测</td><td>✅ 检测</td><td>—</td></tr><tr><td>轻重链比例</td><td>—</td><td>✅ 检测</td></tr><tr><td>去糖基化重链比例</td><td>—</td><td>✅ 检测（反映糖基化效率）</td></tr><tr><td>与传统 SDS-PAGE 比较</td><td>灵敏度高约 10 倍；重现性优；自动化</td><td>同上</td></tr></tbody></table></div><hr><h2 id="唾液酸检测原理-dmb-衍生化荧光-hplc-法" tabindex="-1"><a class="header-anchor" href="#唾液酸检测原理-dmb-衍生化荧光-hplc-法"><span>唾液酸检测原理：DMB 衍生化荧光 HPLC 法</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>唾液酸（Sialic Acid，SA）是抗体 N 糖末端修饰的重要组成部分，其定量检测采用反相 HPLC-荧光法（RP-HPLC-FLD），以 1,2-二氨基-4,5-亚甲二氧基苯（DMB）为荧光衍生化试剂。</p><h3 id="唾液酸的化学基础" tabindex="-1"><a class="header-anchor" href="#唾液酸的化学基础"><span>唾液酸的化学基础</span></a></h3><p>唾液酸（Sialic Acid）是一类含 9 个碳原子的酸性氨基糖，具有吡喃糖环结构，最主要的两种形式为：</p><table><thead><tr><th>形式</th><th>缩写</th><th>结构特征</th><th>在单抗中的意义</th></tr></thead><tbody><tr><td><strong>N-乙酰神经氨酸（5 位连乙酰基）</strong></td><td>NANA / Neu5Ac</td><td>最常见的唾液酸形式</td><td>CHO 细胞产生的主要唾液酸形式</td></tr><tr><td><strong>N-羟乙酰神经氨酸（5 位乙酰基发生羟基化）</strong></td><td>NGNA / Neu5Gc</td><td>NANA 的羟基化衍生物</td><td>CHO 细胞可产生少量 NGNA；具有免疫原性风险（人体对 NGNA 存在天然抗体）</td></tr></tbody></table><h3 id="dmb-衍生化荧光检测原理" tabindex="-1"><a class="header-anchor" href="#dmb-衍生化荧光检测原理"><span>DMB 衍生化荧光检测原理</span></a></h3><p><strong>衍生化反应机制：</strong></p><ol><li>在酸性水解条件下，将 N 糖末端的唾液酸从糖链上释放（通常用 2 M 乙酸，80°C，3 小时）</li><li>释放的唾液酸与 DMB（1,2-二氨基-4,5-亚甲二氧基苯）在酸性条件下发生<strong>柱前衍生反应</strong></li><li>DMB 与唾液酸的羰基反应，导致唾液酸吡喃糖环开环，形成具有荧光特性的喹喔啉衍生物</li><li>衍生物的荧光激发/发射波长与 DMB 本身不同，大幅降低背景干扰</li></ol><p><strong>检测灵敏度优势：</strong> 该方法<strong>高度灵敏和特异</strong>，可检测到痕量唾液酸（ng 级别），适合单抗中低水平唾液酸（0%～2%）的精确定量。</p><h3 id="检测流程" tabindex="-1"><a class="header-anchor" href="#检测流程"><span>检测流程</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>样品（含 N 糖唾液酸的单抗）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>酸性水解（2 M 乙酸，80°C，3 h）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>DMB 衍生化（50°C，2.5 h）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>RP-HPLC 分离（C18 柱，乙腈-水梯度洗脱）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>荧光检测器（Ex 373 nm / Em 448 nm）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>以 NANA 和 NGNA 外标定量</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>报告 NANA%、NGNA%（及 NANA/NGNA 比值）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ngna-的特殊监管关注" tabindex="-1"><a class="header-anchor" href="#ngna-的特殊监管关注"><span>NGNA 的特殊监管关注</span></a></h3><ul><li>人体对 NGNA 存在天然的 IgG 抗体，NGNA 修饰的单抗可能触发免疫反应</li><li>须监控批次间 NGNA 的水平，通常要求 NGNA 含量尽量低（&lt; 1%）</li><li>不同培养基配方和细胞株的 NGNA 产生水平不同，须在工艺开发初期评估</li></ul></div><hr><h2 id="细胞库生长特性表征的核心检定内容" tabindex="-1"><a class="header-anchor" href="#细胞库生长特性表征的核心检定内容"><span>细胞库生长特性表征的核心检定内容</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>细胞库表征（Cell Bank Characterization）不仅包括安全性检定（病毒/微生物），还须对细胞的生物学特性进行全面评估，以证明细胞库的均一性、遗传稳定性和生产适用性。</p><h3 id="生长特性表征" tabindex="-1"><a class="header-anchor" href="#生长特性表征"><span>生长特性表征</span></a></h3><table><thead><tr><th>检测内容</th><th>检测指标</th><th>评估目的</th></tr></thead><tbody><tr><td><strong>细胞生长曲线</strong></td><td>活细胞密度（VCD）、细胞活率、倍增时间</td><td>确认各代次细胞的增殖能力稳定</td></tr><tr><td><strong>比生产速率（qP）</strong></td><td>单位细胞·单位时间产生的目标蛋白量</td><td>评估生产性能的代次稳定性</td></tr><tr><td><strong>代谢特征</strong></td><td>葡萄糖消耗速率、乳酸产生速率、氨积累水平</td><td>确认代谢表型在代次间一致</td></tr></tbody></table><h3 id="细胞染色体检查" tabindex="-1"><a class="header-anchor" href="#细胞染色体检查"><span>细胞染色体检查</span></a></h3><table><thead><tr><th>检测内容</th><th>方法</th><th>评估目的</th></tr></thead><tbody><tr><td><strong>核型分析（Karyotyping）</strong></td><td>G 带染色 + 显微镜观察</td><td>确认染色体数目和结构的整体稳定性（CHO 细胞通常为近二倍体，含少量染色体重排）</td></tr><tr><td><strong>FISH（荧光原位杂交）</strong></td><td>目的基因特异性探针 + 荧光显微镜</td><td>确认外源基因的整合位点和拷贝数分布</td></tr></tbody></table><h3 id="细胞均一性及稳定性检查" tabindex="-1"><a class="header-anchor" href="#细胞均一性及稳定性检查"><span>细胞均一性及稳定性检查</span></a></h3><p><strong>基因型稳定性：</strong></p><ul><li>目的基因拷贝数（建库时 vs EOPC，须无显著变化）</li><li>目的基因测序（MCB vs EOPC，序列须完全一致）</li><li>表达构建体完整性（Southern Blot 分析整合位点模式）</li></ul><p><strong>表型稳定性：</strong></p><ul><li>产品表达量（滴度）在批准代次范围内须稳定</li><li>产品质量属性（CQA：糖型、电荷变体、聚体等）在代次间须保持一致</li></ul><h3 id="各类细胞库的检定适用范围" tabindex="-1"><a class="header-anchor" href="#各类细胞库的检定适用范围"><span>各类细胞库的检定适用范围</span></a></h3><blockquote><p>《中国药典》三部规定：细胞库建立后应至少对 MCB 细胞及生产终末细胞（EOPC）进行一次全面检定。当生产工艺发生改变时，应重新对 EOPC 进行检测。每次从 MCB 建立一个新的 WCB，均应按规定项目进行检定。</p></blockquote></div><hr><h2 id="鉴别试验的法规要求与推荐方法" tabindex="-1"><a class="header-anchor" href="#鉴别试验的法规要求与推荐方法"><span>鉴别试验的法规要求与推荐方法</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>鉴别试验（Identification Test）是证明产品身份特异性的基础检定项目，须在质量标准中明确规定，并具备高度特异性，能将目标产品与其他物质明确区分。</p><h3 id="法规对鉴别试验特异性的要求" tabindex="-1"><a class="header-anchor" href="#法规对鉴别试验特异性的要求"><span>法规对鉴别试验特异性的要求</span></a></h3><p>鉴别试验应<strong>高度特异</strong>——即在所有可能存在于制品中的其他成分存在的情况下，仍能唯一识别目标产品。可根据制品特性选择以下一种或多种方法：</p><table><thead><tr><th>方法类型</th><th>代表技术</th><th>特异性基础</th></tr></thead><tbody><tr><td><strong>免疫学方法（最常用）</strong></td><td>免疫印迹（Western Blot）、ELISA</td><td>利用特异性抗体识别目标蛋白的抗原表位</td></tr><tr><td><strong>理化方法</strong></td><td>毛细管区带电泳（CZE）、毛细管等电聚焦（cIEF）、HPLC</td><td>利用目标蛋白的理化特性（分子量、pI、保留时间）进行特征性比较</td></tr><tr><td><strong>生物学方法</strong></td><td>体外细胞结合活性、ELISA 亲和力测定</td><td>利用目标蛋白特有的生物学活性</td></tr></tbody></table><h3 id="免疫印迹法-western-blot-的规范要求" tabindex="-1"><a class="header-anchor" href="#免疫印迹法-western-blot-的规范要求"><span>免疫印迹法（Western Blot）的规范要求</span></a></h3><ul><li><strong>须设置标准分子量 Marker：</strong> 用于确认目标蛋白条带的分子量位置</li><li><strong>建议设转移前电泳对照：</strong> 确认上样均一性和转移效率</li><li><strong>结合与参比品的比较：</strong> 目标蛋白条带的分子量和染色强度须与参比品一致</li></ul><h3 id="色谱法鉴别的注意事项" tabindex="-1"><a class="header-anchor" href="#色谱法鉴别的注意事项"><span>色谱法鉴别的注意事项</span></a></h3><p>当采用 HPLC（如 SEC-HPLC、CEX-HPLC）进行鉴别时：</p><ul><li>须通过与参比品（Reference Standard）的保留时间比较确认身份</li><li><strong>质量标准描述中须同时规定主要峰或条带的成分和比例控制</strong>（仅凭保留时间一致不足以完整鉴别产品）</li><li>色谱法鉴别须与其他原理的方法联合使用，单一色谱法通常不足以作为完整的鉴别体系</li></ul></div><hr><h2 id="纯度与有关物质分析的法规要求与方法选择" tabindex="-1"><a class="header-anchor" href="#纯度与有关物质分析的法规要求与方法选择"><span>纯度与有关物质分析的法规要求与方法选择</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>纯度和有关物质（Related Substances）分析是生物制品质量标准的核心内容，须采用多种互补原理的分析方法系统评估，全面覆盖产品相关杂质的种类和水平。</p><h3 id="法规要求-双法原则" tabindex="-1"><a class="header-anchor" href="#法规要求-双法原则"><span>法规要求：双法原则</span></a></h3><p><strong>须至少采用两种不同原理的分析方法进行检定</strong>，现行版药典通常要求：</p><table><thead><tr><th>方法</th><th>原理</th><th>检测对象</th></tr></thead><tbody><tr><td><strong>非还原 SDS-PAGE</strong></td><td>按分子大小电泳分离，天然构象条件</td><td>完整性（主带）、聚体（高分子量条带）、片段（低分子量条带）</td></tr><tr><td><strong>HPLC（多种模式）</strong></td><td>按不同理化性质色谱分离</td><td>SEC（聚体/片段）、CEX（电荷变体）、反相（脱酰胺化等修饰）</td></tr></tbody></table><h3 id="sds-page-的操作规范要求" tabindex="-1"><a class="header-anchor" href="#sds-page-的操作规范要求"><span>SDS-PAGE 的操作规范要求</span></a></h3><table><thead><tr><th>染色方式</th><th>最低上样量</th><th>特点</th></tr></thead><tbody><tr><td><strong>银染法（灵敏度高）</strong></td><td>≥ 5 μg</td><td>可检出极低含量次带；检测限约 1 ng/条带</td></tr><tr><td><strong>考马斯亮蓝染色</strong></td><td>≥ 10 μg</td><td>操作较简便；适合常规分析；线性范围更宽</td></tr></tbody></table><p><strong>产品纯度接受标准（一般要求）：</strong> 经扫描，产品纯度应至少 <strong>&gt; 95%</strong>。</p><p><strong>次带（含量 &lt; 5%）的处置原则：</strong></p><ul><li>须对次带的性质进行分析（鉴定对应的蛋白成分）</li><li>须在质量标准的质控方法描述中体现次带的识别和控制</li><li>须评估次带与制品活性、体内代谢和免疫原性的关系</li></ul><h3 id="hplc-方法的多模式组合建议" tabindex="-1"><a class="header-anchor" href="#hplc-方法的多模式组合建议"><span>HPLC 方法的多模式组合建议</span></a></h3><p>建议同时采用多种分离原理的 HPLC 方法，须明确色谱柱型号及选择理由：</p><table><thead><tr><th>HPLC 模式</th><th>色谱柱类型</th><th>主要检测对象</th></tr></thead><tbody><tr><td><strong>分子筛色谱（SEC-HPLC）</strong></td><td>TSKgel G3000SWXL 等</td><td>单体纯度、聚体、片段</td></tr><tr><td><strong>离子交换色谱（CEX-HPLC）</strong></td><td>ProPac WCX-10 等</td><td>电荷变体（酸性峰、主峰、碱性峰）</td></tr><tr><td><strong>反相液相色谱（RP-HPLC）</strong></td><td>C4、C8 柱</td><td>氧化、去酰胺化等化学修饰产物</td></tr></tbody></table><p><strong>多峰出现时的处置原则：</strong> 当 HPLC 分离出现多个峰时，说明蛋白质存在不均一性，须尽可能鉴定各峰对应的异构体成分，分析其与制品活性、体内代谢或免疫原性的关系，必要时在质量标准中对各峰比例进行限度控制。</p></div><hr><h2 id="残余宿主细胞-dna-的检定要求与限度制定原则" tabindex="-1"><a class="header-anchor" href="#残余宿主细胞-dna-的检定要求与限度制定原则"><span>残余宿主细胞 DNA 的检定要求与限度制定原则</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>宿主细胞 DNA（Host Cell DNA，rDNA）是生物制品中重要的工艺相关杂质，残余 DNA 的检定须符合药典规定的方法要求，并依据产品暴露情况制定科学合理的限度。</p><h3 id="法规要求的检测方法" tabindex="-1"><a class="header-anchor" href="#法规要求的检测方法"><span>法规要求的检测方法</span></a></h3><table><thead><tr><th>方法</th><th>原理</th><th>当前状态</th></tr></thead><tbody><tr><td><strong>DNA 探针杂交法（Slot Blot）</strong></td><td>以放射性或酶标记的宿主细胞 DNA 探针检测样品中的残余 DNA</td><td>中国药典和 WHO 认可的传统方法</td></tr><tr><td><strong>荧光染色法（PicoGreen 法）</strong></td><td>PicoGreen 试剂与 dsDNA 结合后产生荧光，定量检测 DNA 浓度</td><td>操作简便，常用于工艺开发阶段</td></tr><tr><td><strong>定量 PCR（qPCR）</strong></td><td>针对宿主细胞特异性 DNA 序列进行实时定量 PCR</td><td><strong>正在研究用于替代传统方法</strong>；灵敏度更高，特异性更好</td></tr></tbody></table><h3 id="限度制定原则" tabindex="-1"><a class="header-anchor" href="#限度制定原则"><span>限度制定原则</span></a></h3><p><strong>一般要求：残余 DNA &lt; 10 ng/剂量</strong></p><p>这一限度基于以下风险考量：</p><ul><li>病毒致癌基因（Oncogene）的潜在转化风险</li><li>DNA 片段大小影响风险：DNA 片段 &lt; 200 bp 通常认为无法整合至宿主基因组</li></ul><p><strong>提高限度标准的情形：</strong></p><table><thead><tr><th>情形</th><th>要求</th></tr></thead><tbody><tr><td>采用<strong>致瘤性风险较大的哺乳动物细胞系</strong>（如某些 HEK293 来源）生产</td><td>须制定<strong>更严格</strong>的 DNA 残留量控制限度</td></tr><tr><td>人体<strong>暴露量较大</strong>的制品（高剂量、频繁给药）</td><td>须制定更严格的限度，并考虑患者的累积暴露量</td></tr><tr><td>新产品拟用药剂量显著高于同类已批准产品</td><td>须根据临床实际适当提高标准，不能直接套用 10 ng/剂量的通用限度</td></tr></tbody></table><h3 id="dna-去除工艺验证" tabindex="-1"><a class="header-anchor" href="#dna-去除工艺验证"><span>DNA 去除工艺验证</span></a></h3><p>除批放行检测外，须对下游纯化工艺的 DNA 去除能力进行验证：</p><ul><li>关键去除步骤：Protein A 层析（流穿，通常 &gt; 99% 去除）、阴离子交换层析（结合去除）</li><li>验证须包含最差情况（Worst Case）研究，证明在参数边缘条件下仍能达到 DNA 去除目标</li></ul></div><hr><h2 id="残余宿主细胞蛋白-hcp-的检定要求与限度制定" tabindex="-1"><a class="header-anchor" href="#残余宿主细胞蛋白-hcp-的检定要求与限度制定"><span>残余宿主细胞蛋白（HCP）的检定要求与限度制定</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>宿主细胞蛋白（Host Cell Proteins，HCP）是生物制品中最复杂的工艺相关杂质，其残留水平须通过经验证的方法精确检测，并结合临床用药暴露量制定合理限度。</p><h3 id="主要检测方法-elisa" tabindex="-1"><a class="header-anchor" href="#主要检测方法-elisa"><span>主要检测方法：ELISA</span></a></h3><p><strong>行业普遍采用 ELISA 法</strong>，分为两类：</p><p><strong>① 商业化通用 HCP ELISA 试剂盒（如 CHO HCP ELISA，Cygnus Technologies）：</strong></p><ul><li>针对 CHO 宿主细胞蛋白谱制备多克隆抗体，覆盖尽可能多的 HCP 种类</li><li>快速、便捷；适合常规批放行</li><li><strong>须进行适用性分析（Suitability Analysis）：</strong> 确认试剂盒抗体对本产品工艺产生的 HCP 谱具有充分覆盖率（Coverage Analysis），避免系统性低估某些 HCP 的含量</li></ul><p><strong>② 定制化 HCP ELISA：</strong></p><ul><li>针对具体生产工艺和细胞株制备专属抗体</li><li>适合商业化通用试剂盒覆盖率不足（&lt; 70%）的情形</li><li>开发成本高，周期长，通常在后期开发阶段才建立</li></ul><h3 id="高级补充方法-lc-ms-ms-hcp-分析" tabindex="-1"><a class="header-anchor" href="#高级补充方法-lc-ms-ms-hcp-分析"><span>高级补充方法：LC-MS/MS HCP 分析</span></a></h3><p>随着质谱技术的普及，LC-MS/MS 正成为 HCP 表征的重要补充手段：</p><ul><li>可直接鉴定 HCP 的蛋白质种类（而非总量）</li><li>对 ELISA 无法覆盖的特定 HCP 进行靶向定量</li><li>特别适用于识别高风险 HCP（如蛋白酶类、磷脂酶等）</li></ul><h3 id="hcp-限度制定原则" tabindex="-1"><a class="header-anchor" href="#hcp-限度制定原则"><span>HCP 限度制定原则</span></a></h3><p><strong>通用参考限度：</strong> 大部分已批准上市生物制品的残余 HCP 含量规定在 <strong>&lt; 0.1%（1,000 ppm，即 ≤ 1 ng HCP/mg 产品）以下</strong>。</p><p><strong>须制定更严格限度的情形：</strong></p><table><thead><tr><th>情形</th><th>影响</th></tr></thead><tbody><tr><td>高剂量给药（单次 &gt; 100 mg）</td><td>患者的绝对 HCP 暴露量大，须更严格控制</td></tr><tr><td>频繁重复给药（长期用药）</td><td>累积 HCP 暴露量升高，免疫原性风险增加</td></tr><tr><td>特定高风险 HCP 类别（如磷脂酶 A2）残留</td><td>该类 HCP 具有生物活性，须单独设立限度</td></tr></tbody></table><p><strong>注意：</strong> HCP 限度须结合产品的临床给药方案（剂量、频率、给药途径、适应症人群）综合评估，不能一律套用已批准产品的限度。</p></div><hr><h2 id="生物技术药物及其检测方法的特殊性" tabindex="-1"><a class="header-anchor" href="#生物技术药物及其检测方法的特殊性"><span>生物技术药物及其检测方法的特殊性</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>生物技术药物（主要是蛋白质/多肽类药物）与小分子化学药物在理化性质和检测方法上存在根本性差异，这些差异决定了其质量标准和检定方法验证的特殊要求。</p><h3 id="生物技术药物的固有特殊性" tabindex="-1"><a class="header-anchor" href="#生物技术药物的固有特殊性"><span>生物技术药物的固有特殊性</span></a></h3><table><thead><tr><th>特殊性</th><th>具体体现</th><th>对检测方法的影响</th></tr></thead><tbody><tr><td><strong>分子量大</strong></td><td>单抗 ~150 kDa，远大于小分子药物（&lt; 500 Da）</td><td>需要特殊分析工具（MS、SEC、电泳）；无法用 HPLC 简单分离</td></tr><tr><td><strong>结构多样性和可变性</strong></td><td>翻译后修饰（PTM）种类多，微小结构变化影响活性</td><td>须采用多种互补方法全面表征</td></tr><tr><td><strong>稳定性差</strong></td><td>对酸、碱、温度、氧化、光照敏感</td><td>须严格控制样品处理条件；须建立特定稳定性规程</td></tr><tr><td><strong>批间生物学变异性</strong></td><td>细胞培养的固有变异性导致批间质量属性存在一定范围的波动</td><td>质量标准须基于合理的批次数据设定，而非理想值</td></tr></tbody></table><h3 id="生物学测定方法的变异性" tabindex="-1"><a class="header-anchor" href="#生物学测定方法的变异性"><span>生物学测定方法的变异性</span></a></h3><table><thead><tr><th>方法类型</th><th>典型结果变异系数（CV）范围</th><th>原因</th></tr></thead><tbody><tr><td>化学结合试验（如 ELISA）</td><td>5%～20%</td><td>生物体系较为稳定，重现性相对好</td></tr><tr><td>酶反应试验</td><td>CV ≤ 20%</td><td>酶促反应受温度和时间影响，须严格控制</td></tr><tr><td>体外细胞测定</td><td>约 30%</td><td>细胞本身具有固有变异性</td></tr><tr><td>动物体内试验</td><td>可达 50%</td><td>动物个体差异大，须使用足够样本量</td></tr></tbody></table><p><strong>关键推论：</strong> 生物技术药物质量标准的特殊性（宽松的接受标准、半定量方法的接受等）主要由<strong>生物学测定方法的变异性</strong>决定，这与小分子药物的精确理化测定有根本区别。</p><h3 id="生物技术药物检测的双重挑战" tabindex="-1"><a class="header-anchor" href="#生物技术药物检测的双重挑战"><span>生物技术药物检测的双重挑战</span></a></h3><ol><li><strong>结构不均一性（Heterogeneity）：</strong> 单抗本身具有固有异质性（糖型、电荷变体等），难以用单一数值描述，须用分布范围表征</li><li><strong>生物活性测量的复杂性：</strong> 活性（Potency）检测依赖活体系统，须以标准品（Reference Standard）为参照进行相对效力（Relative Potency）计算</li></ol></div><hr><h2 id="生物制品检测实验室的三类方法与适用性评估" tabindex="-1"><a class="header-anchor" href="#生物制品检测实验室的三类方法与适用性评估"><span>生物制品检测实验室的三类方法与适用性评估</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>生物制品检测实验室使用的分析方法按其来源和验证状态可分为三类，不同类别的方法在应用前须经过不同程度的验证，须根据方法类型制定相应的验证策略。</p><h3 id="三类方法的定义与验证要求" tabindex="-1"><a class="header-anchor" href="#三类方法的定义与验证要求"><span>三类方法的定义与验证要求</span></a></h3><p><strong>① 经过验证的方法（Validated Methods）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>已被多家实验室广泛研究，或由政府部门/国际组织（WHO、NMPA、药典委员会）要求各级检定实验室使用的方法</td></tr><tr><td><strong>代表</strong></td><td>《中国药典》收录的方法；ICH 指南推荐的标准方法</td></tr><tr><td><strong>验证要求</strong></td><td>方法本身已完成正式验证；但在<strong>第一次应用于某实验室时，须进行方法转移验证（Method Transfer）</strong>，证明实验操作达到要求</td></tr><tr><td><strong>转移验证内容</strong></td><td>通常包括：精密度（中间精密度）、准确性（如适用）、系统适用性测试</td></tr></tbody></table><p><strong>② 来自参考文献的方法（Literature Methods）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>在专业杂志或书籍上发表并介绍的方法</td></tr><tr><td><strong>适用性</strong></td><td>通常较适合检测特定制品，但在应用于<strong>同类制品或其他产品</strong>时，须进行全面验证</td></tr><tr><td><strong>验证要求</strong></td><td><strong>须进行全面验证</strong>（包括专属性、准确性、精密度、线性等所有适用参数）</td></tr><tr><td><strong>注意事项</strong></td><td>文献方法的验证数据通常来自特定样品基质，在不同基质中的适用性须重新评估</td></tr></tbody></table><p><strong>③ 新建立的方法（New Methods）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>为提高检测灵敏度或满足特定要求而新开发的方法，或对原方法进行实质性修改后的方法</td></tr><tr><td><strong>验证要求</strong></td><td><strong>须进行最严格的完整验证</strong>，须考虑并验证方法的专属性、灵敏度、精密度、准确性、方法适用性等全部参数</td></tr><tr><td><strong>使用前提</strong></td><td>在作为常规检定方法使用前，须完成所有验证工作并经质量管理体系批准</td></tr></tbody></table><h3 id="方法选择的优先级原则" tabindex="-1"><a class="header-anchor" href="#方法选择的优先级原则"><span>方法选择的优先级原则</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>优先级（从高到低）：</span></span>
<span class="line"><span>1. 药典方法（ChP/USP/EP）→ 法规可接受性最高</span></span>
<span class="line"><span>2. 监管机构认可的指导原则方法</span></span>
<span class="line"><span>3. 文献方法（须全面验证）</span></span>
<span class="line"><span>4. 内部新建方法（须最严格验证）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><hr><h2 id="生物技术药物活性测定的四类方法及其特点" tabindex="-1"><a class="header-anchor" href="#生物技术药物活性测定的四类方法及其特点"><span>生物技术药物活性测定的四类方法及其特点</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>生物学活性（Biological Activity/Potency）是生物技术药物质量标准中最重要的效力指标，须采用能反映产品作用机制（Mechanism of Action，MoA）的生物学方法进行测定，并以国际或国家标准品为参照进行相对效力计算。</p><h3 id="四类活性测定方法" tabindex="-1"><a class="header-anchor" href="#四类活性测定方法"><span>四类活性测定方法</span></a></h3><p><strong>① 化学结合试验（Binding Assays）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>原理</strong></td><td>不依赖活体生物系统，基于产品与靶分子的结合特性或化学反应</td></tr><tr><td><strong>代表方法</strong></td><td>ELISA（抗原-抗体结合）、SPR（表面等离子体共振）、BLI（生物层干涉）</td></tr><tr><td><strong>结果变异</strong></td><td>变异系数（CV）通常 5%～20%</td></tr><tr><td><strong>主要用途</strong></td><td>纯化过程监测、清洁验证；辅助功能描述</td></tr><tr><td><strong>局限性</strong></td><td><strong>不能作为制品效力测定的单一依据</strong>——结合测定的分子不一定都具有完整生物活性（如脱酰胺化产物可能结合但活性降低）</td></tr></tbody></table><p><strong>② 酶反应试验（Enzyme-based Assays）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>原理</strong></td><td>产品在体外能促进酶分子活化（辅助因子）或本身具备酶活性，通过底物变化（颜色、荧光、发光）检测酶活性</td></tr><tr><td><strong>代表方法</strong></td><td>溶圈法（重组链激酶活性）；酯酶活性法</td></tr><tr><td><strong>结果变异</strong></td><td>CV 通常 ≤ 20%</td></tr><tr><td><strong>关键影响因素</strong></td><td>温度和反应时间须严格控制（酶促反应对温度高度敏感）</td></tr></tbody></table><p><strong>③ 体外细胞测定试验（Cell-based Assays）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>原理</strong></td><td>产品作用于靶细胞，产生可测定的应答（细胞增殖、抑制、凋亡、细胞因子释放等）</td></tr><tr><td><strong>代表方法</strong></td><td>细胞增殖抑制法（肿瘤治疗性抗体）；ADCC 活性测定；CDC 活性测定；细胞结合法</td></tr><tr><td><strong>结果变异</strong></td><td>CV 可达约 <strong>30%</strong></td></tr><tr><td><strong>质量保证要求</strong></td><td>须精心操作以保证试验结果一致性；须使用固定代次的细胞；须设标准品和阴性对照</td></tr><tr><td><strong>监管首选</strong></td><td>对于直接通过细胞效应发挥药效的产品，体外细胞测定通常是监管机构优先接受的效力方法</td></tr></tbody></table><p><strong>④ 动物体内试验（In vivo Animal Studies）</strong></p><table><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>原理</strong></td><td>在动物模型中评估产品的生物学效应，与已知标准品（未处理动物对照）比较</td></tr><tr><td><strong>结果变异</strong></td><td>CV 可达约 <strong>50%</strong></td></tr><tr><td><strong>主要挑战</strong></td><td>动物个体差异大；操作周期长（数天至数周）；须使用大量动物（成本高，伦理压力大）</td></tr><tr><td><strong>适用场景</strong></td><td>体外方法无法充分反映产品作用机制时（如疫苗效力测定、部分激素类产品）</td></tr><tr><td><strong>3R 原则</strong></td><td>替代（Replace）、减少（Reduce）、优化（Refine）——监管机构鼓励用体外方法替代动物试验，须提供科学依据</td></tr></tbody></table><h3 id="方法选择的核心原则" tabindex="-1"><a class="header-anchor" href="#方法选择的核心原则"><span>方法选择的核心原则</span></a></h3><p><strong>生物活性方法须与产品的作用机制（MoA）直接相关：</strong></p><ul><li>以 ADCC 为主要机制的抗体 → 须有 ADCC 活性测定</li><li>以靶点结合抑制信号通路为机制的抗体 → 须有靶点结合或细胞功能抑制试验</li><li>单纯结合试验通常不足以作为效力测定的唯一方法</li></ul></div><hr><h2 id="生物技术药物检测方法验证的核心内容框架" tabindex="-1"><a class="header-anchor" href="#生物技术药物检测方法验证的核心内容框架"><span>生物技术药物检测方法验证的核心内容框架</span></a></h2><div class="hint-container answer"><p class="hint-container-title"><span class="answer-icon" aria-hidden="true"></span><span class="answer-title-text">回答</span><span class="answer-chip">BioCloudHub</span></p><p>生物技术药物检测方法的验证（Analytical Method Validation）是方法合规性的核心要求，须根据方法的用途系统评估并记录一系列验证参数，为监管申报和日常质量控制提供科学依据。</p><h3 id="方法验证的九大核心参数" tabindex="-1"><a class="header-anchor" href="#方法验证的九大核心参数"><span>方法验证的九大核心参数</span></a></h3><table><thead><tr><th>验证参数</th><th>英文名称</th><th>定义</th><th>评估方式</th></tr></thead><tbody><tr><td><strong>专属性</strong></td><td>Specificity</td><td>在其他组分共存时，方法检测目标分析物的能力</td><td>在干扰物存在时与纯净样品比较</td></tr><tr><td><strong>准确性</strong></td><td>Accuracy</td><td>测定值与真实值的接近程度</td><td>已知浓度加标回收实验；与参比方法比较</td></tr><tr><td><strong>精密度</strong></td><td>Precision</td><td>重复测定结果的一致程度</td><td>重复性（n ≥ 6）、中间精密度（不同日/人/仪器）、重现性（不同实验室）</td></tr><tr><td><strong>线性</strong></td><td>Linearity</td><td>方法测定值与分析物浓度之间的线性关系</td><td>至少 5 个浓度水平；计算回归系数 R²</td></tr><tr><td><strong>测定范围</strong></td><td>Range</td><td>方法可以精确测定分析物浓度的区间</td><td>由线性范围和精密度/准确性共同确定</td></tr><tr><td><strong>检测限</strong></td><td>Detection Limit (LOD)</td><td>可以检测到分析物存在的最低浓度（不要求定量）</td><td>信噪比法（S/N = 3:1）；空白标准差法</td></tr><tr><td><strong>定量限</strong></td><td>Quantitation Limit (LOQ)</td><td>可以精确定量的最低分析物浓度</td><td>信噪比法（S/N = 10:1）；须同时满足精密度和准确性要求</td></tr><tr><td><strong>特殊性（耐用性）</strong></td><td>Robustness</td><td>方法在小幅偏离规定条件时的抗干扰能力</td><td>系统化改变小参数（pH ±0.1、温度 ±2°C、柱批次等），评估对结果的影响</td></tr><tr><td><strong>耐用性</strong></td><td>Ruggedness</td><td>方法在不同实验室、操作者之间的重现能力</td><td>与重现性验证相似；通常在方法转移验证中评估</td></tr></tbody></table><h3 id="不同方法类型对验证参数的要求" tabindex="-1"><a class="header-anchor" href="#不同方法类型对验证参数的要求"><span>不同方法类型对验证参数的要求</span></a></h3><table><thead><tr><th>方法用途</th><th>须验证的核心参数</th></tr></thead><tbody><tr><td><strong>鉴别试验</strong></td><td>专属性（唯一能证明身份的关键参数）</td></tr><tr><td><strong>限量检查（纯度/杂质）</strong></td><td>专属性、检测限、精密度、准确性</td></tr><tr><td><strong>定量测定（主成分含量/效力）</strong></td><td>所有九大参数（全面验证）</td></tr><tr><td><strong>生物活性方法（效力）</strong></td><td>特别关注精密度（各层次）和线性；须确定相对效力计算方法</td></tr></tbody></table><h3 id="生物活性方法验证的特殊考量" tabindex="-1"><a class="header-anchor" href="#生物活性方法验证的特殊考量"><span>生物活性方法验证的特殊考量</span></a></h3><p>生物活性方法（Cell-based Assay）的验证除上述参数外，还须特别关注：</p><ul><li><strong>系统适用性（System Suitability）：</strong> 每次运行须设置标准品和阴性对照，确认细胞状态和试验条件合格</li><li><strong>相对效力计算方法验证：</strong> 须证明样品和标准品的量效曲线具有平行性（Parallelism），方可进行相对效力计算</li><li><strong>参考标准品（Reference Standard）管理：</strong> 须建立、表征并定期更新工作参考标准品；须规定每批次参考标准品的标化方案</li></ul></div>`,66))])}const m=e(p,[["render",c]]),H=JSON.parse('{"path":"/posts/cmc-knowledge/06-analytical-methods-quality-standards-01-01.html","title":"过程指标方法原理与验证","lang":"zh-CN","frontmatter":{"title":"过程指标方法原理与验证","date":"2026-03-06T10:30:00.000Z","category":"CMC 核心技术","tags":["CMC","分析方法","质量标准"],"author":"BioCloudHub","description":"分析方法与质量标准：过程指标、方法验证与杂质标准：过程指标方法原理与验证 本页围绕\\"过程指标、方法验证与杂质标准\\"中\\"方法原理与指标认知\\"核心知识点展开，涵盖关键过程指标（乳酸、氨、糖型）的控制范围、主流分析方法（SEC/CEX/CE-SDS/HPLC-PA）的检测原理、细胞库表征要求、纯度与杂质检定标准，以及生物技术药物检测方法的特殊性与验证框架，共...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"过程指标方法原理与验证\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-03-06T10:30:00.000Z\\",\\"dateModified\\":null,\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"BioCloudHub\\"}]}"],["meta",{"property":"og:url","content":"https://biocloudhub.github.io/blogs/posts/cmc-knowledge/06-analytical-methods-quality-standards-01-01.html"}],["meta",{"property":"og:site_name","content":"BioCloudHub"}],["meta",{"property":"og:title","content":"过程指标方法原理与验证"}],["meta",{"property":"og:description","content":"分析方法与质量标准：过程指标、方法验证与杂质标准：过程指标方法原理与验证 本页围绕\\"过程指标、方法验证与杂质标准\\"中\\"方法原理与指标认知\\"核心知识点展开，涵盖关键过程指标（乳酸、氨、糖型）的控制范围、主流分析方法（SEC/CEX/CE-SDS/HPLC-PA）的检测原理、细胞库表征要求、纯度与杂质检定标准，以及生物技术药物检测方法的特殊性与验证框架，共..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:author","content":"BioCloudHub"}],["meta",{"property":"article:tag","content":"质量标准"}],["meta",{"property":"article:tag","content":"分析方法"}],["meta",{"property":"article:tag","content":"CMC"}],["meta",{"property":"article:published_time","content":"2026-03-06T10:30:00.000Z"}]]},"git":{},"readingTime":{"minutes":42.64,"words":12791},"filePathRelative":"posts/cmc-knowledge/06-analytical-methods-quality-standards-01-01.md","excerpt":"\\n<blockquote>\\n<p>本页围绕\\"过程指标、方法验证与杂质标准\\"中\\"方法原理与指标认知\\"核心知识点展开，涵盖关键过程指标（乳酸、氨、糖型）的控制范围、主流分析方法（SEC/CEX/CE-SDS/HPLC-PA）的检测原理、细胞库表征要求、纯度与杂质检定标准，以及生物技术药物检测方法的特殊性与验证框架，共 22 个知识点。</p>\\n</blockquote>\\n<p><em>以下内容用于专业学习与团队知识沉淀，具体项目判断请结合产品类型、项目阶段、法规要求和实验数据综合评估。</em></p>\\n<ul>\\n<li><a href=\\"/blogs/posts/cmc-knowledge/06-analytical-methods-quality-standards-01.html\\" target=\\"_blank\\">返回二级主题总览</a></li>\\n<li><a href=\\"/blogs/posts/cmc-knowledge/06-analytical-methods-quality-standards.html\\" target=\\"_blank\\">返回一级专题总览</a></li>\\n<li><a href=\\"/blogs/posts/cmc-knowledge/06-analytical-methods-quality-standards-01-02.html\\" target=\\"_blank\\">下一细分主题</a></li>\\n</ul>","autoDesc":true}');export{m as comp,H as data};
